1. **API 클라이언트 (src/lib/api-client.ts):**
```typescript
const API_URL = process.env.NEXT_PUBLIC_API_URL || '/api'

class ApiClient {
  private async request<T>(endpoint: string, options?: RequestInit): Promise<T> {
    const response = await fetch(`${API_URL}${endpoint}`, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options?.headers,
      },
    })

    if (!response.ok) {
      throw new Error(`API 에러: ${response.statusText}`)
    }

    return response.json()
  }

  // GET 요청
  async get<T>(endpoint: string): Promise<T> {
    return this.request<T>(endpoint, { method: 'GET' })
  }

  // POST 요청
  async post<T>(endpoint: string, data: unknown): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'POST',
      body: JSON.stringify(data),
    })
  }

  // PUT 요청
  async put<T>(endpoint: string, data: unknown): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'PUT',
      body: JSON.stringify(data),
    })
  }

  // DELETE 요청
  async delete<T>(endpoint: string): Promise<T> {
    return this.request<T>(endpoint, { method: 'DELETE' })
  }
}

export const apiClient = new ApiClient()
```

2. **SWR Hooks (src/lib/hooks/use-portfolio-data.ts):**
```typescript
import useSWR from 'swr'
import { apiClient } from '@/lib/api-client'
import type { Profile, Timeline, Education } from '@/types'

const fetcher = (url: string) => apiClient.get(url)

export function useProfile() {
  const { data, error, isLoading, mutate } = useSWR<Profile>(
    '/profile',
    fetcher,
    {
      revalidateOnFocus: false,
      dedupingInterval: 60000, // 1분
    }
  )

  return {
    profile: data,
    isLoading,
    isError: error,
    mutate,
  }
}

export function useTimeline() {
  const { data, error, isLoading } = useSWR<Timeline[]>(
    '/timeline',
    fetcher
  )

  return {
    timeline: data,
    isLoading,
    isError: error,
  }
}

export function useEducation() {
  const { data, error, isLoading } = useSWR<Education[]>(
    '/education',
    fetcher
  )

  return {
    education: data,
    isLoading,
    isError: error,
  }
}

// ... 나머지 hooks
```

3. **SWR Provider (app/layout.tsx에 추가):**
```typescript
import { SWRConfig } from 'swr'

export default function RootLayout({ children }) {
  return (
    <html lang="ko">
      <body>
        <SWRConfig
          value={{
            refreshInterval: 0,
            revalidateOnFocus: false,
          }}
        >
          {children}
        </SWRConfig>
      </body>
    </html>
  )
}
```

**Alternative: TanStack Query (React Query v5):**
```typescript
import { useQuery } from '@tanstack/react-query'

export function useProfile() {
  return useQuery({
    queryKey: ['profile'],
    queryFn: () => apiClient.get<Profile>('/profile'),
    staleTime: 60000,
  })
}
```

**Best Practices:**
- SWR 권장 (가볍고 Next.js와 잘 통합됨)
- 에러 핸들링을 위한 Error Boundary 추가
- 로딩 상태는 Suspense 또는 skeleton UI 사용

