1. **타임라인 컴포넌트 (src/components/sections/timeline-section.tsx):**
```typescript
'use client'

import { useTimeline } from '@/lib/hooks/use-portfolio-data'
import { Card, CardContent } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Calendar, Building } from 'lucide-react'

export function TimelineSection() {
  const { timeline, isLoading } = useTimeline()

  if (isLoading) {
    return <TimelineSkeleton />
  }

  if (!timeline || timeline.length === 0) {
    return <div className="text-center text-gray-500">타임라인 데이터가 없습니다.</div>
  }

  // sort_order 기준으로 정렬
  const sortedTimeline = [...timeline].sort((a, b) => b.sort_order - a.sort_order)

  return (
    <div className="space-y-6">
      {sortedTimeline.map((item) => (
        <Card key={item.id} className="relative pl-8 before:absolute before:left-3 before:top-0 before:h-full before:w-0.5 before:bg-gray-200">
          <div className="absolute left-0 top-6 h-6 w-6 rounded-full bg-primary text-primary-foreground flex items-center justify-center">
            <Calendar className="h-3 w-3" />
          </div>
          <CardContent className="pt-6">
            <div className="flex items-start justify-between">
              <div>
                <Badge variant="outline" className="mb-2">
                  {item.year}년
                </Badge>
                <h3 className="text-xl font-bold flex items-center gap-2">
                  <Building className="h-5 w-5" />
                  {item.company}
                </h3>
                <p className="text-sm text-muted-foreground">{item.role}</p>
              </div>
            </div>
            {item.description && (
              <p className="mt-3 text-sm">{item.description}</p>
            )}
            {item.events && item.events.length > 0 && (
              <ul className="mt-4 space-y-2">
                {item.events.map((event, idx) => (
                  <li key={idx} className="flex items-start gap-2 text-sm">
                    <span className="mt-1 h-1.5 w-1.5 rounded-full bg-primary" />
                    {event}
                  </li>
                ))}
              </ul>
            )}
          </CardContent>
        </Card>
      ))}
    </div>
  )
}

function TimelineSkeleton() {
  return (
    <div className="space-y-6">
      {[1, 2, 3].map((i) => (
        <div key={i} className="h-48 animate-pulse rounded-lg bg-gray-200" />
      ))}
    </div>
  )
}
```

**디자인 특징:**
- 세로 타임라인 레이아웃
- 좌측에 연도/아이콘, 우측에 내용
- 이벤트는 불릿 포인트 리스트로 표시
- 최신 경력이 위에 오도록 정렬

**Best Practices:**
- Intersection Observer로 스크롤 애니메이션 추가 (선택사항)
- 긴 이벤트 목록은 "더보기" 버튼으로 접기/펼치기

