2. **동료평가 컴포넌트 (src/components/sections/peer-reviews-section.tsx):**
```typescript
'use client'

import { useState } from 'react'
import Image from 'next/image'
import Lightbox from 'yet-another-react-lightbox'
import 'yet-another-react-lightbox/styles.css'
import { usePeerReviews } from '@/lib/hooks/use-portfolio-data'
import { Card } from '@/components/ui/card'

export function PeerReviewsSection() {
  const { peerReviews, isLoading } = usePeerReviews()
  const [lightboxOpen, setLightboxOpen] = useState(false)
  const [photoIndex, setPhotoIndex] = useState(0)

  if (isLoading) {
    return <PeerReviewsSkeleton />
  }

  if (!peerReviews || peerReviews.length === 0) {
    return <div className="text-center text-gray-500">동료평가 데이터가 없습니다.</div>
  }

  const sortedReviews = [...peerReviews].sort((a, b) => a.sort_order - b.sort_order)

  const slides = sortedReviews.map((review) => ({
    src: review.image_url,
    alt: review.reviewer_name,
  }))

  return (
    <>
      <div className="grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-4">
        {sortedReviews.map((review, index) => (
          <Card
            key={review.id}
            className="cursor-pointer overflow-hidden transition-transform hover:scale-105"
            onClick={() => {
              setPhotoIndex(index)
              setLightboxOpen(true)
            }}
          >
            <div className="relative aspect-square">
              <Image
                src={review.image_url}
                alt={review.reviewer_name}
                fill
                className="object-cover"
                sizes="(max-width: 768px) 50vw, (max-width: 1200px) 33vw, 25vw"
              />
            </div>
            <div className="p-2 text-center text-sm">
              {review.reviewer_name}
            </div>
          </Card>
        ))}
      </div>

      <Lightbox
        open={lightboxOpen}
        close={() => setLightboxOpen(false)}
        slides={slides}
        index={photoIndex}
      />
    </>
  )
}

function PeerReviewsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-4">
      {[1, 2, 3, 4].map((i) => (
        <div key={i} className="aspect-square animate-pulse rounded-lg bg-gray-200" />
      ))}
    </div>
  )
}
```

**디자인 특징:**
- 그리드 레이아웃: 모바일 2열, 태블릿 3열, 데스크톱 4열
- 이미지 호버 시 확대 애니메이션
- Lightbox에서 좌우 화살표로 이미지 네비게이션
- 키보드 단축키 지원 (ESC, 화살표)

**Alternative Lightbox Libraries:**
- `react-image-lightbox` (레거시)
- `fslightbox-react` (유료 기능 있음)
- `yet-another-react-lightbox` (권장, 가볍고 현대적)

**Best Practices:**
- Next.js Image 컴포넌트로 이미지 최적화
- Lazy loading으로 초기 로딩 속도 개선
- 접근성: 키보드 네비게이션, alt 텍스트

