// 예시 구현
interface DailyRoutine {
  id: string;
  start_hour: number;
  end_hour: number;
  label: string;
  color: string;
  intensity: string;
}

const DailyRoutineClock: React.FC = () => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const { data: routines } = useSWR<DailyRoutine[]>('/api/daily-routine', fetcher);

  useEffect(() => {
    const timer = setInterval(() => {
      const kstTime = new Date().toLocaleString("en-US", {timeZone: "Asia/Seoul"});
      setCurrentTime(new Date(kstTime));
    }, 60000);
    return () => clearInterval(timer);
  }, []);

  const hourAngle = (currentTime.getHours() % 24) * 15; // 24시간 = 360도
  const minuteAngle = currentTime.getMinutes() * 6; // 60분 = 360도

  return (
    <div className="flex flex-col items-center gap-4">
      <svg width={isMobile ? 280 : 400} height={isMobile ? 280 : 400}>
        {/* 시간대별 루틴 호 렌더링 */}
        {routines?.map(routine => (
          <path
            key={routine.id}
            d={createArcPath(routine.start_hour, routine.end_hour)}
            className={`fill-none stroke-${routine.color} stroke-[8] ${routine.intensity}`}
          />
        ))}
        {/* 시침, 분침 */}
        <line
          x1="50%" y1="50%"
          x2={`${50 + 25 * Math.sin(hourAngle * Math.PI / 180)}%`}
          y2={`${50 - 25 * Math.cos(hourAngle * Math.PI / 180)}%`}
          className="stroke-white stroke-[4]"
        />
        <text x="50%" y="50%" textAnchor="middle" className="fill-white text-sm font-bold">
          small-goliath
        </text>
      </svg>
      <RoutineLegend routines={routines} />
    </div>
  );
};

