// 예시 구현 (동료평가 갤러리)
import Lightbox from "yet-another-react-lightbox";
import "yet-another-react-lightbox/styles.css";

const PeerReviewSection: React.FC = () => {
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [currentImage, setCurrentImage] = useState(0);
  const { data: reviews } = useSWR<PeerReview[]>('/api/peer-reviews', fetcher);

  const openLightbox = (index: number) => {
    setCurrentImage(index);
    setLightboxOpen(true);
  };

  return (
    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
      {reviews?.map((review, index) => (
        <div key={review.id} className="cursor-pointer" onClick={() => openLightbox(index)}>
          <Image
            src={review.image_url}
            alt={`동료평가 ${index + 1}`}
            width={200}
            height={200}
            className="rounded-lg hover:scale-105 transition-transform"
          />
        </div>
      ))}

      <Lightbox
        open={lightboxOpen}
        close={() => setLightboxOpen(false)}
        index={currentImage}
        slides={reviews?.map(review => ({ src: review.image_url })) || []}
      />
    </div>
  );
};

